function d_boids(P,R){var n=P.n||20,b=[];for(var i=0;i<n;i++)b.push({x:R()*10,y:R()*10,vx:(R()-0.5),vy:(R()-0.5)});var cx=0,cy=0;b.forEach(function(p){cx+=p.x;cy+=p.y;});cx/=n;cy/=n;var coh=0;b.forEach(function(p){p.vx+=0.05*(cx-p.x);p.vy+=0.05*(cy-p.y);p.x+=p.vx;p.y+=p.vy;coh+=Math.hypot(p.x-cx,p.y-cy);});return{agents:n,mean_distance_to_centroid:+(coh/n).toFixed(3),cohesion:'increasing'};}

